  ListTodo, DollarSign,
  BarChart3
} from "lucide-react";
import { RestaurantLayoutEditor } from "@/components/seat-builder/restaurant-layout-editor";
import type { BusinessType } from "@/lib/schema";
import type { AutoTableTab } from "@/components/auto-admin";
